sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    gs.info('CORPOSITORY OCR BR: Started for record ' + current.getDisplayValue());

    // =========================================
    // SAFE NUMBER FUNCTION
    // =========================================
    function num(fieldName) {

        var val = current.getValue(fieldName);

        // Handle blank, NA, dash
        if (!val || val == 'NA' || val == '-') {
            return 0;
        }

        return parseFloat(val) || 0;
    }

    // =========================================
    // FETCH VALUES
    // =========================================
    var totalRevenue        = num('total_revenue');
    var costOfGoodsSold     = num('cost_of_goods_sold');
    var purchasesOfStock    = num('purchases_of_stock');
    var accountsPayable     = num('acc_payable');
    var workingCapTurnover  = num('wcc_turnover');

    // =========================================
    // GROSS PROFIT MARGIN %
    // Formula:
    // ((Revenue - (COGS + Purchases))
    // / Revenue) * 100
    // =========================================
    var grossProfitPercent = 0;

    if (totalRevenue > 0) {

        grossProfitPercent =
            (
                (
                    totalRevenue -
                    (
                        costOfGoodsSold +
                        purchasesOfStock
                    )
                ) / totalRevenue
            ) * 100;
    }

    // =========================================
    // A/P DAYS
    // Formula:
    // (Accounts Payable / Cost Of Goods Sold) * 365
    // =========================================
    var apDays = 0;

    if (costOfGoodsSold > 0) {

        apDays =
            (
                accountsPayable /
                costOfGoodsSold
            ) * 365;
    }

    // =========================================
    // NET WCC DAYS
    // Formula:
    // 365 / Working Capital Turnover
    // =========================================
    var netWccDays = 0;

    if (workingCapTurnover !== 0) {

        netWccDays =
            365 / workingCapTurnover;
    }

    // =========================================
    // ROUND VALUES
    // =========================================
    grossProfitPercent = parseFloat(grossProfitPercent.toFixed(2));
    apDays             = parseFloat(apDays.toFixed(2));
    netWccDays         = parseFloat(netWccDays.toFixed(2));

    // =========================================
    // STORE VALUES
    // =========================================
    current.setValue('gross_profit', grossProfitPercent);
    current.setValue('ap_days', apDays);
    current.setValue('net_wcc_days', netWccDays);

    gs.info('Gross Profit % Calculated: ' + grossProfitPercent);
    gs.info('AP Days Calculated: ' + apDays);
    gs.info('Net WCC Days Calculated: ' + netWccDays);

})(current, previous);
